<template><div class="app-container"><el-alert title="配置变更仅影响后续提交的单据，已生成的审批任务不会自动改变。" type="info" show-icon class="mb8"/><el-form label-width="150px"><el-form-item label="主管审批候选人"><el-select v-model="supervisors" multiple filterable><el-option v-for="u in users" :key="u.userId" :label="`${u.nickName}（${u.userName}）`" :value="String(u.userId)"/></el-select></el-form-item><el-form-item label="财务审批候选人"><el-select v-model="finances" multiple filterable><el-option v-for="u in users" :key="u.userId" :label="`${u.nickName}（${u.userName}）`" :value="String(u.userId)"/></el-select></el-form-item><el-button type="primary" @click="save">保存配置</el-button></el-form></div></template>
<script setup lang="ts" name="SupplyWorkflowConfig">
import { listUser } from '@/api/system/user'; import { listWorkflowConfigs, saveWorkflowConfig } from '@/api/supply'; import type { SysUser } from '@/types'
const { proxy }=getCurrentInstance()!; const users=ref<SysUser[]>([]); const supervisors=ref<string[]>([]); const finances=ref<string[]>([]); async function load(){const [u,c]=await Promise.all([listUser({pageNum:1,pageSize:100,status:'0'}),listWorkflowConfigs()]);users.value=u.rows;const item=c.data?.find((x:any)=>x.flowType==='INVOICE_APPROVAL')||c.data?.find((x:any)=>x.flowType==='PURCHASE_ORDER_APPROVAL');if(item){supervisors.value=(item.supervisorCandidates||'').split(',').filter(Boolean);finances.value=(item.financeCandidates||'').split(',').filter(Boolean)}};async function save(){const supervisorCandidates=supervisors.value.join(',');await saveWorkflowConfig({flowType:'SUPPLIER_ONBOARDING',supervisorCandidates});await saveWorkflowConfig({flowType:'INVOICE_APPROVAL',supervisorCandidates,financeCandidates:finances.value.join(',')});await saveWorkflowConfig({flowType:'PURCHASE_ORDER_APPROVAL',supervisorCandidates});proxy.$modal.msgSuccess('流程配置已保存');load()};load()
</script>
